// EffectiveKind is Kind as a reader reads it (SPEC.md § 8.1): a kind it does not know, or none, is an app.
func (m Homebrew) EffectiveKind() string {
	if m.Kind != nil {
		for _, v := range Kinds {
			if v == *m.Kind {
				return v
			}
		}
	}
	return "app"
}

// EffectiveGenres is Genres as a reader reads them (SPEC.md § 7.1): one it does not know is other.
func (m Homebrew) EffectiveGenres() []string {
	var out []string
	seen := map[string]bool{}
	for _, g := range m.Genres {
		if !contains(Genres, g) {
			g = "other"
		}
		if !seen[g] {
			seen[g] = true
			out = append(out, g)
		}
	}
	return out
}

