// EffectiveGenres is Genres as a reader reads them (SPEC.md § 7.1): one it does not know is other.
func (m Title) EffectiveGenres() []string {
	var out []string
	seen := map[string]bool{}
	for _, g := range m.Genres {
		if !contains(Genres, g) {
			g = "other"
		}
		if !seen[g] {
			seen[g] = true
			out = append(out, g)
		}
	}
	return out
}

